#include <cassert>
#include <iostream>
#include <regex>
#include <string>

int main() {
    std::string sentence{"Friday the thirteenth."};
    const std::regex re{"([A-z]+) ([a-z]+) ([a-z]+)"};
    std::smatch words;
    std::regex_search(sentence, words, re);
    std::cout << std::boolalpha;
    for (const auto &m : words) {
        assert(m.matched);
        std::cout << "m: [" << m << "], m.length(): " << m.length()
                  << ", "
                     "*m.first: '"
                  << *m.first
                  << "', "
                     "*m.second: '"
                  << *m.second << "'\n";
    }
}
